#!/usr/bin/env node
/**
 * Repository check (runs in CI): keeps the codebase lean.
 *  - no big files in git (photos, cookbooks, and test books live in Cloud Storage or are
 *    generated by the tests, never committed);
 *  - no media or archives outside the app's own icons;
 *  - secrets and local settings stay out (.env.local, service-account keys).
 */
import { fileURLToPath } from 'node:url'
import { execFileSync } from 'node:child_process'
import { readFileSync, statSync } from 'node:fs'
import { join } from 'node:path'

const root = fileURLToPath(new URL('..', import.meta.url))
const MAX_FILE = 400 * 1024
const MAX_TOTAL = 8 * 1024 * 1024
/** Lock files are generated and large by nature. */
const BIG_OK = new Set(['package-lock.json', 'functions/package-lock.json'])
const MEDIA = /\.(pdf|epub|zip|gz|tgz|7z|rar|mp4|mov|m4v|webm|mp3|wav|heic|psd|apk|jar|exe|dmg)$/i
const IMAGE = /\.(png|jpe?g|gif|webp|avif|bmp|tiff?)$/i
const IMAGE_OK = /^public\/[^/]+\.(png|ico|svg|webp)$/

const tracked = execFileSync('git', ['ls-files', '-z'], { cwd: root }).toString('utf8').split('\0').filter(Boolean)
const problems = []
let total = 0
for (const f of tracked) {
  let size = 0
  try {
    size = statSync(join(root, f)).size
  } catch {
    continue // deleted in the working tree
  }
  if (!BIG_OK.has(f)) total += size
  if (size > MAX_FILE && !BIG_OK.has(f)) problems.push(`${f}: ${Math.round(size / 1024)} kB (limit ${MAX_FILE / 1024} kB per file).`)
  if (MEDIA.test(f)) problems.push(`${f}: media and archives don't belong in git (tests build their own fixtures).`)
  if (IMAGE.test(f) && !IMAGE_OK.test(f)) problems.push(`${f}: images belong in public/ (app icons) or Cloud Storage.`)
  if (/(^|\/)\.env(\.|$)(?!example)/.test(f)) problems.push(`${f}: environment files stay local.`)
  if (/service[-_]?account.*\.json$|-firebase-adminsdk-.*\.json$/i.test(f)) problems.push(`${f}: looks like a service-account key; never commit credentials.`)
}
if (total > MAX_TOTAL) problems.push(`Tracked files total ${Math.round(total / 1024)} kB (limit ${MAX_TOTAL / 1024} kB, lock files excluded).`)

const ignore = readFileSync(join(root, '.gitignore'), 'utf8')
for (const must of ['node_modules', 'dist', '.env.local']) {
  if (!ignore.split(/\r?\n/).some((l) => l.trim().replace(/^\//, '').replace(/\/$/, '') === must || l.trim() === `*.local` && must === '.env.local')) problems.push(`.gitignore should ignore ${must}.`)
}

console.log(`  ${tracked.length} files, ${Math.round(total / 1024)} kB tracked (lock files excluded)`)
if (problems.length) {
  console.error(`\nRepository check failed (${problems.length}):`)
  for (const p of problems) console.error(`  ✗ ${p}`)
  process.exit(1)
}
console.log('Repository check passed.')
